import itertools
import json

def solve_puzzle():
    # Input variables for the puzzle
    houses = [1, 2]
    names = ["Eric", "Arnold"]
    book_genres = ["science fiction", "mystery"]
    birthdays = ["april", "sept"]
    animals = ["horse", "cat"]

    solutions = []

    # Try all permutations while applying constraints
    for perm_names in itertools.permutations(names):
        # Clue 1: Eric is in the first house.
        if perm_names[0] != "Eric":
            continue

        for perm_genres in itertools.permutations(book_genres):
            # Clue 3: The person who loves science fiction books is in the second house.
            if perm_genres[1] != "science fiction":
                continue

            for perm_birthdays in itertools.permutations(birthdays):
                # Clue 2: Eric is the person whose birthday is in September.
                idx_eric = perm_names.index("Eric")
                if perm_birthdays[idx_eric] != "sept":
                    continue

                for perm_animals in itertools.permutations(animals):
                    # Clue 4: The person who keeps horses is the person whose birthday is in September.
                    idx_sept = perm_birthdays.index("sept")
                    if perm_animals[idx_sept] != "horse":
                        continue

                    # Build the solution rows in house order
                    rows = []
                    for i, house in enumerate(houses):
                        rows.append([
                            str(house),
                            perm_names[i],
                            perm_genres[i],
                            perm_birthdays[i],
                            perm_animals[i]
                        ])
                    solution = {
                        "solution": {
                            "header": ["House", "Name", "BookGenre", "Birthday", "Animal"],
                            "rows": rows
                        }
                    }
                    solutions.append(solution)

    # Output the first valid solution found (puzzle should be unique)
    if solutions:
        return solutions[0]
    else:
        return {
            "solution": {
                "header": ["House", "Name", "BookGenre", "Birthday", "Animal"],
                "rows": []
            }
        }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
